	failed_path := get_failed_path(result)
	fixed_path := get_fixed_path(result)
	msga := {
		"alertMessage": sprintf("%v: %v has pods running in the 'default' namespace", [wl.kind, wl.metadata.name]),
		"packagename": "armo_builtins",
