no_label_or_no_label_usage(wl, start_of_path) := path if {
	not wl.metadata
	label_key := get_label_key("")
	path = [{"path": sprintf("%vmetadata.labels[%v]", [start_of_path, label_key]), "value": "YOUR_VALUE"}]
